const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const depth = String(body.depth || 'macro').toLowerCase();
const maxItems = Number(body.max_items || body.maxItems || 10);
const dryRun = body.dry_run !== false;

const prompt = [
  'Desde project/planning/current-state-baseline.yaml, planifica el proyecto desde el estado actual, no desde cero.',
  `Nivel de detalle: ${depth}.`,
  `Maximo de items candidatos: ${maxItems}.`,
  'Usa project/roadmap/roadmap-6-months.yaml, project/backlog/master-backlog.yaml, project/backlog/epic-map.yaml, project/kanban/board.yaml, project/agents-operating-model.md y project/roles/expert-role-catalog.yaml.',
  'Produce una salida DRAFT con phase_plan, backlog_gap_analysis, proposed_items agrupados por STORY, ENABLER, SPIKE, EXPERIMENT y TASK, dependencias, riesgos y primeros items recomendados.',
  'Respeta avances existentes de sensores, edge, web y n8n. No propongas reimplementar trabajo existente sin justificar reemplazo.',
  'No muevas estados Kanban, no marques DONE, no edites HU congeladas, no apruebes compras ni control fisico.',
  'Si falta informacion, haz una sola pregunta.'
].join(' ');

return [{
  json: {
    agent: 'project-planning',
    workspace: 'central',
    prompt,
    mode: 'draft',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'WF-PLAN-PROJECT-001',
      agent_id: 'AGENT-PLAN-001',
      depth,
      max_items: maxItems,
      requested_by: body.requested_by || 'chat-gateway'
    }
  }
}];
